fn validate_resting_batch(
    &self,
    orders: &[OrderRequest],
    now_ms: u64,
) -> Result<(), RestingBatchError> {
    if orders.is_empty() {
        return Ok(());
    }

    let side = orders[0].side;
    let mut seen_keys = BTreeSet::new();
    let mut next_sequence = self.next_sequence;
    let mut previous_resting = self.same_side(side).last().cloned();

    for order in orders {
        self.validate_market(order)
            .map_err(RestingBatchError::Reject)?;
        validate_order_request(order, now_ms).map_err(RestingBatchError::Reject)?;

        if order.side != side {
            return Err(RestingBatchError::Unsupported);
        }
        if self.has_active_resting_order(order.account_id, order.client_order_id, now_ms)
            || !seen_keys.insert((order.account_id, order.client_order_id))
        {
            return Err(RestingBatchError::Reject(
                OrderRejectReason::DuplicateClientOrderId,
            ));
        }
        if !matches!(order.kind, OrderKind::Limit { .. })
            || matches!(order.time_in_force, TimeInForce::Ioc | TimeInForce::Fok)
        {
            return Err(RestingBatchError::Unsupported);
        }

        let preview = self
            .preview(order, now_ms)
            .map_err(RestingBatchError::Reject)?;
        let pre_match =
            pre_match_check(order, preview, now_ms).map_err(RestingBatchError::Reject)?;
        if pre_match.crosses_book || pre_match.must_execute_immediately || !pre_match.may_post {
            return Err(RestingBatchError::Unsupported);
        }

        let resting = RestingOrder {
            market_id: order.market_id,
            account_id: order.account_id,
            client_order_id: order.client_order_id,
            side: order.side,
            price_ticks: match order.kind {
                OrderKind::Limit { price_ticks } => price_ticks,
                OrderKind::Market => return Err(RestingBatchError::Unsupported),
            },
            remaining_lots: order.quantity_lots,
            expires_at_ms: match order.time_in_force {
                TimeInForce::Gtt { expires_at_ms } => Some(expires_at_ms),
                _ => None,
            },
            sequence: next_sequence,
        };

        if previous_resting
            .as_ref()
            .is_some_and(|previous| resting_precedes(&resting, previous))
        {
            return Err(RestingBatchError::Unsupported);
        }

        previous_resting = Some(resting);
        next_sequence = next_sequence.saturating_add(1);
    }

    Ok(())
}

pub fn submit_resting_batch(
    &mut self,
    orders: &[OrderRequest],
    now_ms: u64,
) -> Result<Vec<MatchOutcome>, RestingBatchError> {
    if orders.is_empty() {
        return Ok(Vec::new());
    }

    self.purge_expired(now_ms);
    self.validate_resting_batch(orders, now_ms)?;

    let side = orders[0].side;
    let mut restings = Vec::with_capacity(orders.len());
    let mut outcomes = Vec::with_capacity(orders.len());
    let mut keys = Vec::with_capacity(orders.len());

    for order in orders {
        let price_ticks = match order.kind {
            OrderKind::Limit { price_ticks } => price_ticks,
            OrderKind::Market => unreachable!("batch validation rejects market orders"),
        };
        let expires_at_ms = match order.time_in_force {
            TimeInForce::Gtt { expires_at_ms } => Some(expires_at_ms),
            _ => None,
        };
        let sequence = self.allocate_sequence();
        restings.push(RestingOrder {
            market_id: order.market_id,
            account_id: order.account_id,
            client_order_id: order.client_order_id,
            side: order.side,
            price_ticks,
            remaining_lots: order.quantity_lots,
            expires_at_ms,
            sequence,
        });
        keys.push((order.account_id, order.client_order_id, expires_at_ms));
        outcomes.push(MatchOutcome {
            status: MatchStatus::Resting,
            fills: Vec::new(),
            filled_lots: 0,
            remaining_lots: order.quantity_lots,
            posted_order_id: Some(order.client_order_id),
        });
    }

    self.same_side_mut(side).extend(restings);
    for (account_id, client_order_id, expires_at_ms) in keys {
        self.track_resting_key(account_id, client_order_id, expires_at_ms);
    }

    Ok(outcomes)
}

fn resting_precedes(candidate: &RestingOrder, current: &RestingOrder) -> bool {
    match candidate.side {
        OrderSide::Bid => {
            candidate.price_ticks > current.price_ticks
                || (candidate.price_ticks == current.price_ticks
                    && candidate.sequence < current.sequence)
        }
        OrderSide::Ask => {
            candidate.price_ticks < current.price_ticks
                || (candidate.price_ticks == current.price_ticks
                    && candidate.sequence < current.sequence)
        }
    }
}

pub(super) fn try_commit_market_sharded_resting_place_order_batch_inner(
    policy_store: &mut PolicyStore,
    // AllowedCounterparties cannot fire here: validate_resting_batch rejects
    // crossing orders as Unsupported, so batch outcomes have no fills.
    mandates: &BTreeMap<MandateId, Mandate>,
    delegations: &BTreeMap<DelegationId, Delegation>,
    order_books: &mut BTreeMap<u64, SingleMarketBook>,
    resting_order_mandates: &mut BTreeMap<(u64, u64, u64), MandateId>,
    isolated_collateral: &BTreeMap<(u64, u64), i128>,
    frozen_accounts: &BTreeSet<u64>,
    markets: &BTreeMap<u64, PerpetualMarket>,
    paused_markets: &BTreeSet<u64>,
    market_marks: &BTreeMap<u64, OraclePrice>,
    market_index_prices: &BTreeMap<u64, OraclePrice>,
    market_oracle_config: &BTreeMap<u64, OracleConfig>,
    positions: &BTreeMap<(u64, u64), PositionLedger>,
    chain_id: u64,
    body: &BlockBody,
    block_number: u64,
    timestamp_ms: u64,
    worker_market_matching: bool,
    allow_single_shard: bool,
) -> Result<Option<CommitBlockIntentsOutput>, NodeError> {
    if body.items.len() < 2 {
        return Ok(None);
    }

    let mut stats = RestingBatchCommitStats::default();
    let gather_started = Instant::now();
    let mut shards = BTreeMap::<u64, MarketShard>::new();
    let mut signed_by_item = vec![None; body.items.len()];

    for (item_index, item) in body.items.iter().enumerate() {
        let BlockItem::Intent(signed_intent) = item else {
            return Ok(None);
        };
        let Some(order) = order_request_from_place_order_intent(signed_intent) else {
            return Ok(None);
        };
        signed_by_item[item_index] = Some(signed_intent);
        match shards.get_mut(&order.market_id) {
            Some(shard) => {
                if shard.side != order.side {
                    return Ok(None);
                }
                shard.entries.push(MarketShardEntry { item_index, order });
            }
            None => {
                shards.insert(
                    order.market_id,
                    MarketShard {
                        side: order.side,
                        entries: vec![MarketShardEntry { item_index, order }],
                    },
                );
            }
        }
    }

    if !allow_single_shard && shards.len() < 2 {
        return Ok(None);
    }
    stats.gather_ns = duration_nanos_u64(gather_started.elapsed());
    stats.attempts = shards.len() as u64;

    let precheck_started = Instant::now();
    for (market_id, shard) in shards.iter() {
        let orders = shard
            .entries
            .iter()
            .map(|entry| entry.order)
            .collect::<Vec<_>>();
        let batch_check = order_books.get(market_id).map_or_else(
            || SingleMarketBook::new(*market_id).can_submit_resting_batch(&orders, timestamp_ms),
            |book| book.can_submit_resting_batch(&orders, timestamp_ms),
        );
        match batch_check {
            Ok(()) => {}
            Err(RestingBatchError::Unsupported) => {
                return Ok(None);
            }
            Err(RestingBatchError::Reject(reason)) => {
                return Err(NodeError::Order(reason));
            }
        }
        let signed_intents = shard
            .entries
            .iter()
            .map(|entry| {
                signed_by_item[entry.item_index]
                    .expect("sharded entry should have matching signed intent")
            })
            .collect::<Vec<_>>();
        ensure_resting_order_batch_preserves_mandate_position_attribution(
            policy_store,
            order_books,
            resting_order_mandates,
            positions,
            &orders,
            &signed_intents,
            timestamp_ms,
        )?;
        ensure_resting_order_batch_preserves_mandate_max_leverage(
            policy_store,
            mandates,
            order_books,
            isolated_collateral,
            markets,
            market_marks,
            positions,
            &orders,
            &signed_intents,
            timestamp_ms,
        )?;
        ensure_resting_order_batch_preserves_initial_margin(
            order_books,
            isolated_collateral,
            markets,
            market_marks,
            positions,
            &orders,
            timestamp_ms,
        )?;
    }
    stats.precheck_ns = duration_nanos_u64(precheck_started.elapsed());

    let admission_started = Instant::now();
    let admissions = body
        .items
        .iter()
        .filter_map(|item| match item {
            BlockItem::Intent(signed_intent) => Some(signed_intent),
            BlockItem::Transaction(_)
            | BlockItem::OraclePrice(_)
            | BlockItem::Funding(_)
            | BlockItem::Faucet(_)
            | BlockItem::Liquidation(_)
            | BlockItem::Delegation(_)
            | BlockItem::MarketMakerProgram(_)
            | BlockItem::TeeGovernance(_)
            | BlockItem::RealCapitalGovernance(_) => None,
        })
        .map(|signed_intent| {
            validate_intent_runtime_gates(
                signed_intent,
                frozen_accounts,
                markets,
                paused_markets,
                market_marks,
                market_index_prices,
                market_oracle_config,
                timestamp_ms,
            )?;
            let policy_account_scope =
                policy_account_scope_for_intent(policy_store, delegations, signed_intent)?;
            Ok((
                signed_intent,
                policy_admission_for_intent(
                    signed_intent,
                    markets,
                    chain_id,
                    block_number,
                    timestamp_ms,
                )?,
                policy_account_scope,
            ))
        })
        .collect::<Result<Vec<_>, NodeError>>()?;
    stats.admission_ns = duration_nanos_u64(admission_started.elapsed());

    let policy_started = Instant::now();
    for (signed_intent, admission, policy_account_scope) in admissions.iter() {
        commit_stacked_mandate_admission(
            policy_store,
            signed_intent,
            admission,
            *policy_account_scope,
        )?;
        policy_store
            .commit_preverified_admission(signed_intent.intent.policy_id, admission)
            .map_err(NodeError::Policy)?;
    }
    stats.policy_ns = duration_nanos_u64(policy_started.elapsed());

    let matching_started = Instant::now();
    let mut outcomes_by_item = vec![None; body.items.len()];
    if worker_market_matching {
        for output in submit_market_shards_parallel(order_books, &shards, timestamp_ms)? {
            let shard = shards
                .get(&output.market_id)
                .expect("parallel matching should only return known market shards");
            for (entry, outcome) in shard.entries.iter().zip(output.outcomes) {
                outcomes_by_item[entry.item_index] = Some((output.market_id, outcome));
            }
            order_books.insert(output.market_id, output.book);
        }
    } else {
        for (market_id, shard) in shards.iter() {
            let orders = shard
                .entries
                .iter()
                .map(|entry| entry.order)
                .collect::<Vec<_>>();
            let outcomes = order_books
                .entry(*market_id)
                .or_insert_with(|| SingleMarketBook::new(*market_id))
                .submit_resting_batch(&orders, timestamp_ms)
                .map_err(node_error_from_resting_batch_error)?;
            for (entry, outcome) in shard.entries.iter().zip(outcomes) {
                outcomes_by_item[entry.item_index] = Some((*market_id, outcome));
            }
        }
    }
    stats.matching_ns = duration_nanos_u64(matching_started.elapsed());

    let event_started = Instant::now();
    let mut events = Vec::with_capacity(body.items.len().saturating_mul(2));
    for item_index in 0..body.items.len() {
        let signed_intent = signed_by_item[item_index]
            .expect("market-sharded resting batch only stores intent items");
        let (market_id, outcome) = outcomes_by_item[item_index]
            .as_ref()
            .expect("market-sharded resting batch should produce one outcome per item");
        events.push(RuntimeEventKind::IntentExecuted {
            intent_id: intent_id(signed_intent),
            policy_id: signed_intent.intent.policy_id,
            nonce: signed_intent.intent.nonce,
        });
        events.push(order_accepted_event_from_outcome(
            signed_intent,
            *market_id,
            outcome,
        ));
        let order = order_request_from_place_order_intent(signed_intent)
            .expect("market-sharded resting batch only stores place-order intents");
        events.extend(order_fill_events(
            *market_id,
            &outcome.fills,
            intent_origin_mandate_id(policy_store, signed_intent),
            resting_order_mandates,
        ));
        update_resting_order_mandates_from_outcome(
            resting_order_mandates,
            order_books,
            *market_id,
            &order,
            outcome,
            intent_origin_mandate_id(policy_store, signed_intent),
            timestamp_ms,
        );
    }
    stats.event_ns = duration_nanos_u64(event_started.elapsed());
    stats.accepted = shards.len() as u64;
    stats.items = body.items.len() as u64;

    Ok(Some(CommitBlockIntentsOutput {
        events,
        resting_batch_stats: stats,
    }))
}

pub(super) fn try_apply_mahi_resting_body_in_place(
    &mut self,
    parent: &Block,
    effective_round: u64,
    timestamp_ms: u64,
    proposer: ValidatorId,
    body: BlockBody,
    market_marks: &BTreeMap<u64, OraclePrice>,
    market_index_prices: &BTreeMap<u64, OraclePrice>,
    positions: &BTreeMap<(u64, u64), PositionLedger>,
    body_elapsed: std::time::Duration,
    total_started: Instant,
    profile_execution: bool,
) -> Result<bool, NodeError> {
    let commit_started = Instant::now();
    let Some(commit_output) =
        try_commit_market_sharded_resting_place_order_batch_including_single_shard(
            &mut self.policy_store,
            &self.mandates,
            &self.delegations,
            &mut self.order_books,
            &mut self.resting_order_mandates,
            &self.isolated_collateral,
            &self.frozen_accounts,
            &self.markets,
            &self.paused_markets,
            &market_marks,
            &market_index_prices,
            &self.market_oracle_config,
            positions,
            parent.header.chain_id,
            &body,
            parent.header.height.saturating_add(1),
            timestamp_ms,
        )?
    else {
        return Ok(false);
    };
    let resting_batch_stats = commit_output.resting_batch_stats;
    let committed_events = commit_output.events;
    let commit_elapsed = commit_started.elapsed();
    let roots_started = Instant::now();
    let tx_root = body_root(&body);
    let event_root = mahi_runtime_event_root(&committed_events);
    let state_root = mahi_native_state_root(
        &parent.header.state_root,
        &tx_root,
        &event_root,
        effective_round,
        timestamp_ms,
    );
    let roots_elapsed = roots_started.elapsed();
    let block = Block {
        header: BlockHeader {
            chain_id: parent.header.chain_id,
            height: parent.header.height.saturating_add(1),
            round: effective_round,
            proposer,
            parent_hash: block_hash(parent),
            parent_state_root: parent.header.state_root,
            tx_root,
            event_root,
            state_root,
            qc: synthetic_mahi_quorum_certificate(parent),
            timestamp_ms,
        },
        body,
    };
    let install_started = Instant::now();
    self.install_mahi_committed_block_metadata(
        block,
        Vec::new(),
        committed_events,
        Vec::new(),
    )?;
    let install_elapsed = install_started.elapsed();
    self.record_phase6_resting_batch_stats(resting_batch_stats);
    if profile_execution {
        eprintln!(
            "mahi_exec_profile mode=native_inplace body_items={} body_ms={} commit_ms={} roots_ms={} install_ms={} total_ms={}",
            self.head().body.items.len(),
            body_elapsed.as_millis(),
            commit_elapsed.as_millis(),
            roots_elapsed.as_millis(),
            install_elapsed.as_millis(),
            total_started.elapsed().as_millis(),
        );
    }
    Ok(true)
}

pub(super) fn simulation_order_book_for_market(
    simulated_order_books: &mut BTreeMap<u64, SingleMarketBook>,
    order_books: &BTreeMap<u64, SingleMarketBook>,
    market_id: u64,
) {
    if let std::collections::btree_map::Entry::Vacant(entry) =
        simulated_order_books.entry(market_id)
    {
        if let Some(order_book) = order_books.get(&market_id) {
            entry.insert(order_book.clone());
        }
    }
}

pub(super) fn ensure_resting_order_batch_preserves_initial_margin(
    order_books: &BTreeMap<u64, SingleMarketBook>,
    isolated_collateral: &BTreeMap<(u64, u64), i128>,
    markets: &BTreeMap<u64, PerpetualMarket>,
    market_marks: &BTreeMap<u64, OraclePrice>,
    positions: &BTreeMap<(u64, u64), PositionLedger>,
    orders: &[OrderRequest],
    timestamp_ms: u64,
) -> Result<(), NodeError> {
    let mut simulated_order_books = BTreeMap::new();
    for order in orders {
        simulation_order_book_for_market(&mut simulated_order_books, order_books, order.market_id);
        ensure_order_preserves_initial_margin(
            &simulated_order_books,
            isolated_collateral,
            markets,
            market_marks,
            positions,
            order,
            None,
            timestamp_ms,
        )?;
        simulated_order_books
            .entry(order.market_id)
            .or_insert_with(|| SingleMarketBook::new(order.market_id))
            .submit(*order, timestamp_ms)
            .map_err(NodeError::Order)?;
    }
    Ok(())
}

pub fn commit_preverified_admission(
    &mut self,
    policy_id: PolicyId,
    admission: &PolicyAdmission,
) -> Result<(), PolicyError> {
    let delta = match self.preview_preverified_admission(policy_id, admission) {
        Ok(delta) => delta,
        Err(PolicyError::DrawdownExceededAndRevoked) => {
            if !self.policies.contains_key(&policy_id) {
                return Err(PolicyError::UnknownPolicy(policy_id));
            }
            self.cascade_revoke(policy_id, admission.block_number, admission.timestamp_ms);
            return Err(PolicyError::DrawdownExceededAndRevoked);
        }
        Err(error) => return Err(error),
    };
    let policy = self
        .policies
        .get_mut(&policy_id)
        .ok_or(PolicyError::UnknownPolicy(policy_id))?;
    if admission.intent_nonce != policy.next_intent_nonce {
        return Err(PolicyError::InvalidIntentNonce {
            expected: policy.next_intent_nonce,
            actual: admission.intent_nonce,
        });
    }
    policy.counters = delta.counters;
    policy.next_intent_nonce = policy.next_intent_nonce.saturating_add(1);
    Ok(())
}

fn mahi_inplace_resting_commit_advances_state_without_overlay_clone() {
    let signer = signing_key(8);
    let mut engine = SingleNodeEngine::new(single_node_config());
    engine
        .policy_store_mut()
        .insert(sample_policy())
        .expect("policy should insert");
    let body = BlockBody {
        items: vec![
            BlockItem::Intent(signed_intent(
                &signer,
                1,
                10_000,
                IntentKind::PlaceOrder {
                    market_id: 7,
                    client_order_id: 100,
                    side: IntentOrderSide::Bid,
                    quantity_lots: 1,
                    kind: IntentOrderKind::Limit { price_ticks: 100 },
                    time_in_force: IntentTimeInForce::Gtc,
                    post_only: false,
                },
            )),
            BlockItem::Intent(signed_intent(
                &signer,
                2,
                10_000,
                IntentKind::PlaceOrder {
                    market_id: 7,
                    client_order_id: 101,
                    side: IntentOrderSide::Bid,
                    quantity_lots: 1,
                    kind: IntentOrderKind::Limit { price_ticks: 100 },
                    time_in_force: IntentTimeInForce::Gtc,
                    post_only: false,
                },
            )),
        ],
    };
    let parent = engine.head().clone();
    let positions = engine.positions.clone();
    let market_marks = engine.market_marks.clone();
    let market_index_prices = engine.market_index_prices.clone();

    let applied = engine
        .try_apply_mahi_resting_body_in_place(
            &parent,
            1,
            1_200,
            validator(9),
            body,
            &market_marks,
            &market_index_prices,
            &positions,
            std::time::Duration::ZERO,
            std::time::Instant::now(),
            false,
        )
        .expect("in-place resting commit should not error");

    assert!(applied);
    assert_eq!(engine.head().header.height, parent.header.height + 1);
    assert_eq!(
        engine
            .policy_store()
            .get(42)
            .expect("policy should remain present")
            .next_intent_nonce,
        3
    );
    assert!(engine.resting_order(7, 11, 100, 1_200).is_some());
    assert!(engine.resting_order(7, 11, 101, 1_200).is_some());
}

